	for (const surface of ['auto', 'hint', 'any', 'closerequest', 'modal']) for (const activation of [false, true]) for (const veto of ['none', 'cancel', 'beforetoggle', 'keydown']) {
		const popover = surface === 'auto' || surface === 'hint'
