			if (pattern === 'before') await clickElement(requireElement(oracle.document, '#activation'))
			for (const index of [0, 1, 2]) {
				if (pattern === 'between') await clickElement(requireElement(oracle.document, '#activation'))
				const constructor: unknown = Reflect.get(oracle.window, 'CloseWatcher')
				if (typeof constructor !== 'function') throw new Error('Missing CloseWatcher')
				const watcher: EventTarget = Reflect.construct(constructor, [])
				for (const name of ['cancel', 'close']) watcher.addEventListener(name, event => { events.push({ index, name, cancelable: event.cancelable }); if (veto && name === 'cancel') event.preventDefault() })
