			}
			const steps = []
			for (const escape of [1, 2, 3, 4]) { await pressKey('Escape'); steps.push({ escape, events: [...events] }) }
			for (const watcher of watchers) invokeMethod(watcher, 'destroy')
			await recordReading('watchers', { pattern, veto, steps })
		} finally { oracle.destroy() }
	}
}, 15000)

