it('until-found fragment reveal and exclusive details against accordion', async () => {
	for (const variant of ['until-found', 'collapse', 'normalized-collapse', 'hidden']) {
		const oracle = await createOracle({ plugin: 'Collapse', markup: `<div style="height:900px"></div><div id="panel" hidden="${variant === 'hidden' ? '' : 'until-found'}" ${variant.includes('collapse') ? 'class="collapse"' : ''} ${variant === 'normalized-collapse' ? 'style="display:block"' : ''}><p id="match">Find this unique passage</p></div>` })
		try {
			const panel = requireElement(oracle.document, '#panel')
			const events = watchEvents(panel, ['beforematch', 'show.bs.collapse', 'shown.bs.collapse'])
			const before = { hidden: panel.getAttribute('hidden'), box: readBox(panel) }
			oracle.window.location.hash = 'match'
			await waitForDelay(120)
			await recordReading('until-found', { variant, before, after: { hidden: panel.getAttribute('hidden'), box: readBox(panel), class: panel.className, scroll: oracle.window.scrollY }, events })
		} finally { oracle.destroy() }
	}
	for (const veto of [false, true]) {
		const oracle = await createOracle({ plugin: 'Collapse', markup: '<details name="group" id="one" open><summary>One</summary>First</details><details name="group" id="two"><summary id="open-two">Two</summary>Second</details><div id="accordion"><button data-bs-toggle="collapse" data-bs-target="#a">A</button><div class="collapse show" id="a" data-bs-parent="#accordion">First</div><button id="open-b" data-bs-toggle="collapse" data-bs-target="#b">B</button><div class="collapse" id="b" data-bs-parent="#accordion">Second</div></div>' })
		try {
			const details = requireElement(oracle.document, '#two')
			const events = watchEvents(details, ['toggle', 'beforetoggle'])
			if (veto) details.addEventListener('toggle', event => event.preventDefault())
			await clickElement(requireElement(oracle.document, '#open-two'))
			const native = { first: requireElement(oracle.document, '#one').hasAttribute('open'), second: details.hasAttribute('open'), events }
			const a = requireElement(oracle.document, '#a')
			const b = requireElement(oracle.document, '#b')
			const bootstrap = watchEvents(requireElement(oracle.document, '#accordion'), ['show.bs.collapse', 'shown.bs.collapse', 'hide.bs.collapse', 'hidden.bs.collapse'])
			if (veto) b.addEventListener('show.bs.collapse', event => event.preventDefault())
			await clickElement(requireElement(oracle.document, '#open-b'))
			await waitForDelay(400)
			await recordReading('exclusive', { veto, native, bootstrap: { first: a.className, second: b.className, events: bootstrap } })
