it('View Transitions carousel tab reduced motion and waitUntil', async () => {
	try { await recordReading('browser-flags', await cdp().send('Browser.getBrowserCommandLine')) }
	catch (error) { await recordReading('browser-flags', { refused: String(error) }) }
	for (const reduced of [false, true]) for (const family of ['Carousel', 'Tab']) for (const transition of [false, true]) {
		await cdp().send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: reduced ? 'reduce' : 'no-preference' }] })
		const markup = family === 'Carousel' ? '<div id="host" class="carousel slide"><div class="carousel-indicators"><button data-bs-target="#host" data-bs-slide-to="0" class="active" aria-current="true">First</button><button data-bs-target="#host" data-bs-slide-to="1">Second</button></div><div class="carousel-inner"><div class="carousel-item active">First slide</div><div class="carousel-item">Second slide</div></div><button data-bs-target="#host" data-bs-slide="next">Next</button></div>' : '<nav class="nav" role="tablist"><button id="first" class="nav-link active" data-bs-toggle="tab" data-bs-target="#a">First</button><button id="host" class="nav-link" data-bs-toggle="tab" data-bs-target="#b">Second</button></nav><div class="tab-content"><div id="a" class="tab-pane fade show active">First pane</div><div id="b" class="tab-pane fade">Second pane</div></div>'
		const oracle = await createOracle({ plugin: family, markup })
		try {
			const host = requireElement(oracle.document, '#host')
