it('Bootstrap native hide veto reconciliation', async () => {
	for (const plugin of ['Dropdown', 'Offcanvas', 'Modal', 'Popover']) for (const surface of plugin === 'Modal' ? ['any', 'closerequest', 'modal'] : ['auto', 'hint']) for (const veto of [false, true]) {
		const markup = plugin === 'Dropdown' ? `<div class="dropdown"><button id="subject" data-bs-toggle="dropdown">Open</button><div class="dropdown-menu" id="panel" popover="${surface}"><button id="inside">Item</button></div></div>` : plugin === 'Offcanvas' ? `<div class="offcanvas offcanvas-start" id="subject" tabindex="-1" popover="${surface}"><button id="inside">Inside</button></div>` : plugin === 'Modal' ? `<style>dialog.modal[open]{display:block}</style><dialog class="modal" id="subject" tabindex="-1" ${surface === 'modal' ? '' : `closedby="${surface}"`}><div class="modal-dialog"><div class="modal-content"><button id="inside">Inside</button></div></div></dialog>` : '<button id="subject" title="Title" data-bs-content="Content">Popover trigger</button>'
		const oracle = await createOracle({ plugin, markup })
		try {
			const subject = requireElement(oracle.document, '#subject')
