			const events = watchEvents(subject, [`show.bs.${plugin.toLowerCase()}`, `shown.bs.${plugin.toLowerCase()}`, `hide.bs.${plugin.toLowerCase()}`, `hidden.bs.${plugin.toLowerCase()}`, 'keydown', 'cancel', 'close', 'beforetoggle', 'toggle'])
			if (veto) subject.addEventListener(`hide.bs.${plugin.toLowerCase()}`, event => event.preventDefault())
			instance.call('show')
			await waitForDelay(330)
			const panel = plugin === 'Dropdown' ? requireElement(oracle.document, '#panel') : plugin === 'Popover' ? requireElement(oracle.document, '.popover') : subject
			invokeMethod(panel, plugin === 'Modal' ? surface === 'modal' ? 'showModal' : 'show' : 'showPopover')
			invokeMethod(subject, 'focus')
			const shown = { native: plugin === 'Modal' ? panel.hasAttribute('open') : panel.matches(':popover-open'), class: panel.className }
			await pressKey('Escape')
