			const escaped = { native: plugin === 'Modal' ? panel.hasAttribute('open') : panel.matches(':popover-open'), class: panel.className }
			instance.call('hide')
			await waitForDelay(330)
			await recordReading('bootstrap-veto', { plugin, surface, veto, shown, escaped, hidden: { native: plugin === 'Modal' ? panel.hasAttribute('open') : panel.matches(':popover-open'), class: panel.className }, events })
		} finally { oracle.destroy() }
	}
}, 30000)

