import { cdp, commands } from 'vitest/browser'
import { waitForDelay } from '@orkestrel/test'

export function requireElement(root: ParentNode, selector: string) {
	const element = root.querySelector(selector)
	if (!element) throw new Error(`Missing ${selector}`)
	return element
}

export function invokeMethod(target: object, name: string, args: readonly unknown[] = []) {
	const method: unknown = Reflect.get(target, name)
	if (typeof method !== 'function') throw new Error(`Missing method ${name}`)
	return Reflect.apply(method, target, args)
}

export async function recordReading(name: string, data: unknown) {
	await commands.writeFile('tmp/probes/stage-b-measure/readings.jsonl', JSON.stringify({ name, data }) + '\n', { flag: 'a' })
}

export function watchEvents(target: EventTarget, names: readonly string[]) {
	const events: unknown[] = []
	const start = performance.now()
	for (const name of names) target.addEventListener(name, (event) => {
		events.push({ name, time: performance.now() - start, cancelable: event.cancelable, prevented: event.defaultPrevented, target: event.target instanceof Element ? event.target.id : undefined, old: Reflect.get(event, 'oldState'), next: Reflect.get(event, 'newState'), property: Reflect.get(event, 'propertyName'), pseudo: Reflect.get(event, 'pseudoElement'), animation: Reflect.get(event, 'animation')?.constructor?.name })
	})
	return events
}

export async function pressKey(key: string, code = key) {
	await cdp().send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: key === 'Escape' ? 27 : key === 'ArrowRight' ? 39 : key === 'Tab' ? 9 : 0 })
	await cdp().send('Input.dispatchKeyEvent', { type: 'keyUp', key, code })
	await waitForDelay(35)
}

export async function clickElement(element: Element) {
	await invokeMethod(element, 'scrollIntoView', [{ block: 'nearest', behavior: 'instant' }])
	let received = false
	element.addEventListener('click', () => { received = true }, { once: true })
	let x = element.getBoundingClientRect().x + element.getBoundingClientRect().width / 2
	let y = element.getBoundingClientRect().y + element.getBoundingClientRect().height / 2
	let realm = element.ownerDocument.defaultView
	while (realm?.frameElement) {
		const rect = realm.frameElement.getBoundingClientRect()
		x = rect.x + (x + realm.frameElement.clientLeft) * rect.width / (realm.frameElement.clientWidth + realm.frameElement.clientLeft * 2)
		y = rect.y + (y + realm.frameElement.clientTop) * rect.height / (realm.frameElement.clientHeight + realm.frameElement.clientTop * 2)
		realm = realm.parent
	}
	await cdp().send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 })
	await cdp().send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 })
	await waitForDelay(35)
	if (!received) throw new Error(`Pointer missed ${element.id}; point ${x},${y}`)
}

export async function movePointer(element: Element, wheel = 0) {
	let x = element.getBoundingClientRect().x + Math.min(20, element.getBoundingClientRect().width / 2)
	let y = element.getBoundingClientRect().y + Math.min(20, element.getBoundingClientRect().height / 2)
	let realm = element.ownerDocument.defaultView
	while (realm?.frameElement) {
		const rect = realm.frameElement.getBoundingClientRect()
		x = rect.x + (x + realm.frameElement.clientLeft) * rect.width / (realm.frameElement.clientWidth + realm.frameElement.clientLeft * 2)
		y = rect.y + (y + realm.frameElement.clientTop) * rect.height / (realm.frameElement.clientHeight + realm.frameElement.clientTop * 2)
		realm = realm.parent
	}
	await cdp().send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y })
	if (wheel) await cdp().send('Input.dispatchMouseEvent', { type: 'mouseWheel', x, y, deltaX: 0, deltaY: wheel })
	await waitForDelay(180)
}

export function readBox(element: Element) {
	const rect = element.getBoundingClientRect()
	const style = element.ownerDocument.defaultView?.getComputedStyle(element)
	return { x: rect.x, y: rect.y, width: rect.width, height: rect.height, padding: style?.paddingRight, margin: style?.marginRight, overflow: style?.overflow, display: style?.display }
}

export function collectFrames(tree: unknown): string[] {
	if (typeof tree !== 'object' || tree === null) return []
	const frame: unknown = Reflect.get(tree, 'frame')
	const children: unknown = Reflect.get(tree, 'childFrames')
	const ids: string[] = []
	if (typeof frame === 'object' && frame !== null && Reflect.get(frame, 'url') === 'about:srcdoc') ids.push(Reflect.get(frame, 'id'))
	if (Array.isArray(children)) for (const child of children) ids.push(...collectFrames(child))
	return ids
}

export async function readAccessibility() {
	await cdp().send('Accessibility.enable')
	const tree = await cdp().send('Page.getFrameTree')
	const frames = collectFrames(tree.frameTree)
	const nodes: unknown[] = []
	for (const frameId of frames) {
		const result = await cdp().send('Accessibility.getFullAXTree', { frameId })
		nodes.push(...result.nodes)
	}
	return nodes
}

export function collectPseudos(root: unknown): object[] {
	const results: object[] = []
	const stack = [root]
	while (stack.length) {
		const node = stack.pop()
		if (typeof node !== 'object' || node === null) continue
		if ('pseudoType' in node) results.push(node)
		for (const value of Object.values(node)) {
			if (Array.isArray(value)) stack.push(...value)
			else if (typeof value === 'object' && value !== null) stack.push(value)
		}
	}
	return results
}
